/* Guards the one thing this public repository must never publish: a chain seed or any
 * field that is not part of the published commitment.
 *
 * `chains.js` is generated by tools/export.mjs from public endpoints. A generator bug or a
 * hand edit could put a seed there, and the file is served to every visitor, so the build
 * checks its shape before the artifact is uploaded. Run with: node tools/check-public.mjs
 */
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';

const ALLOWED = new Set(['id', 'terminalHash', 'salt', 'saltHeight', 'length', 'committedAt', 'firstRound']);
const HEX64 = /^[0-9a-f]{64}$/i;
const problems = [];

function fail(message) {
  problems.push(message);
}

/* An optional path lets a test point the same check at a fixture. */
const target = process.argv[2] || fileURLToPath(new URL('../chains.js', import.meta.url));
const source = await readFile(target, 'utf8');
if (!/self\s*\.\s*CT_CHAINS\s*=/.test(source)) fail('chains.js does not assign self.CT_CHAINS.');

const sandbox = { self: {} };
let chains;
try {
  vm.runInNewContext(source, sandbox, { timeout: 1000, filename: 'chains.js' });
  chains = sandbox.self.CT_CHAINS;
} catch (error) {
  fail('chains.js does not evaluate: ' + error.message);
}
if (chains !== undefined && !Array.isArray(chains)) fail('CT_CHAINS is not an array.');

(chains || []).forEach((chain, index) => {
  const at = 'chain[' + index + ']';
  if (!chain || typeof chain !== 'object') { fail(at + ' is not an object.'); return; }
  for (const key of Object.keys(chain)) {
    if (!ALLOWED.has(key)) fail(at + ' carries a field that is not published: ' + key);
  }
  if (!Number.isSafeInteger(chain.id) || chain.id < 1) fail(at + ' has no positive integer id.');
  if (typeof chain.terminalHash !== 'string' || !HEX64.test(chain.terminalHash)) {
    fail(at + ' terminalHash is not a 64-character hex hash.');
  }
  if (chain.salt != null && (typeof chain.salt !== 'string' || !HEX64.test(chain.salt))) {
    fail(at + ' salt is not a 64-character hex hash.');
  }
  if (chain.saltHeight != null && (!Number.isSafeInteger(chain.saltHeight) || chain.saltHeight < 0)) {
    fail(at + ' saltHeight is not a block height.');
  }
  if (chain.length != null && (!Number.isSafeInteger(chain.length) || chain.length < 1)) {
    fail(at + ' length is not a positive integer.');
  }
  if (chain.firstRound != null && (!Number.isSafeInteger(chain.firstRound) || chain.firstRound < 1)) {
    fail(at + ' firstRound is not a positive round id.');
  }
});

/* Strings are the only place a secret could hide under an allowed name, so every value is
 * checked for the shape of a seed-bearing payload: a 64-hex string is fine for the anchor
 * and the salt, and nothing else may carry one. */
(chains || []).forEach((chain, index) => {
  for (const key of ['id', 'length', 'saltHeight', 'firstRound']) {
    if (typeof chain[key] === 'string' && HEX64.test(chain[key])) fail('chain[' + index + '].' + key + ' looks like a hash.');
  }
});

if (problems.length) {
  console.error('chains.js is not publishable:');
  for (const problem of problems) console.error('  - ' + problem);
  process.exit(1);
}
console.log('chains.js is publishable: ' + (chains || []).length + ' public chain commitment(s), no seed field.');
